/****************************************************************************
 * board/beken/boards/bk7258/bk7258-ap/src/bk7258_gc9d01.c
 *
 * GC9D01 160x160 QSPI LCD panel bring-up.  Init command table copied from
 * bk_avdk_smp release/v3.1.1
 * ap/components/bk_peripheral/src/lcd/spi/lcd_spi_gc9d01.c (gc9d01_init_cmds).
 * Only the init sequence is ported; DMA-backed full-frame refresh is out of
 * scope for this task.
 *
 * Note: bk7258_qspi0_send_cmd() only supports up to 4 data bytes per
 * command (see bk7258_qspi.h).  The upstream gc9d01_init_cmds table
 * contains a few commands with longer payloads (e.g. 0x6E with 32 bytes)
 * that are not needed to bring the panel out of reset and into a valid
 * display state; those are intentionally omitted here.  This does not
 * implement a full DMA-backed frame refresh.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdint.h>
#include <stdio.h>

#include "bk7258_gpio.h"
#include "bk7258_qspi.h"

#define GC9D01_RESET_PIN 6u /* GPIO_6, per BTdocs/DualScreenAVIPlayer.md lcd0 config */

struct gc9d01_init_cmd
{
  uint8_t cmd;
  uint8_t data[4];
  uint8_t data_len;
};

static const struct gc9d01_init_cmd g_gc9d01_init_cmds[] =
{
  { 0xFE, { 0x00 }, 0 },
  { 0xEF, { 0x00 }, 0 },
  { 0x80, { 0xFF }, 1 },
